@dataclass(frozen=True)
class T:
    run_id:int; shard:int; target:str; seconds:float
def cur(rows):
    if not rows: return []
    a=[[rows[0]]]; first=rows[0].target
    for row in rows[1:]:
        prev=a[-1][-1]
        if row.target==prev.target: a[-1].append(row)
        elif row.target==first: a.append([row]); first=row.target
        else: a[-1].append(row)
    return a
def sw(rows):
    if not rows: return []
    a=[[rows[0]]]; first=rows[0].target
    for row in rows[1:]:
        prev=a[-1][-1]
        if row.target==first: a.append([row]); first=row.target
        elif row.target==prev.target: a[-1].append(row)
        else: a[-1].append(row)
    return a
def total(rows, split, latest):
    a=split(rows); chosen=[a[-1]] if latest else a; return sum(r.seconds for x in chosen for r in x), [[r.seconds for r in x] for x in a]
tests={\"one\":[T(1,1,\"test-a\",10),T(1,1,\"test-b\",5),T(1,1,\"test-a\",12),T(1,1,\"test-b\",8)],\"two\":[T(1,1,\"test-multi\",1),T(1,1,\"test-multi\",2),T(1,1,\"test-multi\",3),T(1,1,\"test-other\",4)],\"three\":[T(1,1,\"test-a\",1),T(1,1,\"test-a\",2),T(1,1,\"test-b\",3),T(1,1,\"test-a\",4),T(1,1,\"test-a\",5),T(1,1,\"test-b\",6)]}
for name, rows in tests.items():
    print(name)
    for label, split, latest in [(\"current\",cur,True),(\"no-latest\",cur,False),(\"swapped\",sw,True),(\"both\",sw,False)]: print(label,total(rows,split,latest))'"

